using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.Security.Cryptography;using System.Text.RegularExpressions;
namespace V15Voice {
public sealed class VoiceReportContext {
 public string SourcePath="",VoiceKey="",Description="",UserNote="",Styles="",VoiceSource="",Purpose="Tạo WAV";
 public List<Cue> SourceCues;
 public Action<VoiceRenderReport> Written;
}
public sealed class VoiceReportAttempt {public double Speed,Measured,Target;public string Note;}
public sealed class VoiceReportUnit {
 public string Speaker="A",Voice="",VoiceKey="",Engine="",ReferenceHash="";public int Number,Stage;public string Text,Status="Chưa chạy tới",Error="",Detail="";public List<int> CueIds=new List<int>();public bool ExactMap;
 public double? Before,After,Start,End,Speed,WorkingBefore,Target,RequiredSpeed,Tts,OriginalStart,OriginalEnd;public double PauseBefore,PauseAfter,Reserve,GapBefore,BreathBefore,GapAfter,BreathAfter;
 public bool GapAfterKnown;public int CacheCalls,GeneratedCalls;public List<VoiceReportAttempt> Attempts=new List<VoiceReportAttempt>();
}
public sealed class VoiceReportStage {
 public int Number;public double Start,End;public string Text="",Status="Chưa chạy tới",Reason="";public double? Before,After,Speed,RequiredSpeed,Tts,InnerPauses,BetweenPauses,Breaths;public double TailAdjustment;
 public List<int> CueIds=new List<int>();public List<VoiceReportAttempt> Attempts=new List<VoiceReportAttempt>();
}
public sealed partial class VoiceRenderReport {
 readonly object sync=new object();readonly RenderOptions options;readonly KokoroEngine engine;readonly VoiceReportContext context;readonly Stopwatch timer=Stopwatch.StartNew();readonly DateTime started=DateTime.UtcNow;
 readonly List<Cue> sources;readonly List<Tuple<int,int,int>> spans=new List<Tuple<int,int,int>>();readonly string flat;int matchCursor,spanCursor;
 readonly Queue<VoiceReportUnit> pendingStageUnits=new Queue<VoiceReportUnit>();
 readonly List<string> devices=new List<string>();readonly string sourceHash,referenceHash,rawSource="";
 public readonly List<VoiceReportUnit> Units=new List<VoiceReportUnit>();public readonly List<VoiceReportStage> Stages=new List<VoiceReportStage>();
 string activeSpeaker="A",activeVoice="",activeKey="",activeEngine="",activeReference="";
 public void SelectVoice(string role,string key,KokoroEngine selected){lock(sync){activeSpeaker=role;activeKey=String.IsNullOrEmpty(key)?(role=="B"?options.VoiceBKey:options.VoiceAKey):key;if(activeKey.Length==0)activeKey=context.VoiceKey;activeVoice=selected.VoiceName??"";activeEngine=selected.Kind+" / "+selected.ModelFolder+" / speaker "+selected.Speaker;activeReference=FileHash(selected.ReferencePath);}}
 VoiceReportUnit lastTimelineUnit;public VoiceReportUnit Current;public VoiceReportStage CurrentStage;public string PathName="",SaveWarning="",Outcome="ĐANG CHẠY",Error="",Wav="";public bool Complete;
 static readonly CultureInfo CI=CultureInfo.InvariantCulture;
 public static List<Cue> Snapshot(IEnumerable<Cue> input){return (input??new List<Cue>()).Select(c=>new Cue{Id=c.Id,Start=c.Start,End=c.End,Text=c.Text,Speaker=c.Speaker,Prose=c.Prose,AnchorAfter=c.AnchorAfter,ParagraphEnd=c.ParagraphEnd}).ToList();}
 static string Norm(string s){return Regex.Replace(s??"",@"\s+"," ").Trim();}
 static string HashText(string s){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(s))).Replace("-","").ToLowerInvariant();}
 static string FileHash(string path){try{return !String.IsNullOrEmpty(path)&&File.Exists(path)?StateFiles.Hash(path).ToLowerInvariant():"chưa có";}catch{return "không đọc được";}}
 public VoiceRenderReport(List<Cue> input,KokoroEngine owner,RenderOptions o,string output){
  engine=owner;options=o??new RenderOptions();context=options.ReportContext??new VoiceReportContext();sources=Snapshot(context.SourceCues??input);sourceHash=FileHash(context.SourcePath);referenceHash=FileHash(owner==null?null:owner.ReferencePath);if(sources.Count==0)try{if(!String.IsNullOrEmpty(context.SourcePath)&&File.Exists(context.SourcePath)&&new FileInfo(context.SourcePath).Length<=5*1024*1024)rawSource=File.ReadAllText(context.SourcePath);}catch{}
  var b=new StringBuilder();foreach(var c in sources){if(b.Length>0)b.Append(' ');int start=b.Length;b.Append(Norm(c.Text));spans.Add(Tuple.Create(c.Id,start,b.Length));}flat=b.ToString();
  if(options.Anchored)try{PlanStages(AnchoredVoice.Plan(Snapshot(input)));}catch{}
  string basis=String.IsNullOrEmpty(context.SourcePath)?output:context.SourcePath;
  string stem;try{stem=System.IO.Path.GetFileNameWithoutExtension(basis);if(String.IsNullOrEmpty(stem))stem="kich_ban";}catch{stem="kich_ban";}
  var folders=new List<string>();try{folders.Add(System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(basis)));}catch{}
  folders.Add(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"V15VoiceStudio","reports"));
  foreach(string folder in folders)try{Directory.CreateDirectory(folder);for(int i=0;i<10000;i++){string name=System.IO.Path.Combine(folder,stem+".voice-report"+(i==0?"":" ("+(i+1)+")")+".txt");FileStream stream;try{stream=new FileStream(name,FileMode.CreateNew,FileAccess.Write,FileShare.Read);}catch(IOException){if(File.Exists(name)||Directory.Exists(name))continue;throw;}try{using(stream){PathName=name;byte[] text=Encoding.UTF8.GetBytes(Build());stream.Write(text,0,text.Length);}break;}catch{PathName="";try{File.Delete(name);}catch{}throw;}}if(PathName.Length>0)break;}catch(Exception e){SaveWarning="Chưa ghi báo cáo cạnh nguồn: "+e.Message;}
  if(PathName.Length==0)SaveWarning="Không lưu được báo cáo. "+SaveWarning;Notify();
 }
 void Notify(){if(context.Written!=null)try{context.Written(this);}catch{}}
 void Append(string text){if(PathName.Length==0)return;try{File.AppendAllText(PathName,"\r\n[TIẾN TRÌNH "+timer.Elapsed.TotalSeconds.ToString("0.000",CI)+"s] "+text+"\r\n",new UTF8Encoding(false));}catch(Exception e){SaveWarning="Lỗi lưu tiến trình báo cáo: "+e.Message;}}
 public VoiceReportStage BeginStage(AnchorStage s){lock(sync){PlanStages(new[]{s});CurrentStage=Stages.Single(x=>x.Number==s.Number);CurrentStage.Status="Đang đọc/căn";Append("Bắt đầu chặng "+s.Number);return CurrentStage;}}
 VoiceReportUnit MakeUnit(string text,int stage){var u=new VoiceReportUnit{Number=Units.Count+1,Stage=stage,Text=text,Speaker=activeSpeaker,Voice=activeVoice,VoiceKey=activeKey,Engine=activeEngine,ReferenceHash=activeReference};int at=flat.IndexOf(Norm(text),matchCursor,StringComparison.Ordinal);if(at>=0){int end=at+Norm(text).Length;while(spanCursor<spans.Count&&spans[spanCursor].Item3<=at)spanCursor++;for(int i=spanCursor;i<spans.Count&&spans[i].Item2<end;i++)u.CueIds.Add(spans[i].Item1);u.ExactMap=true;matchCursor=end;}else if(CurrentStage!=null)u.CueIds=new List<int>(CurrentStage.CueIds);Units.Add(u);return u;}
 public void PlanStageUnits(int stage,List<string> texts){lock(sync){pendingStageUnits.Clear();foreach(string text in texts)pendingStageUnits.Enqueue(MakeUnit(text,stage));}}
 public void BeginUnit(string text,int stage=0){lock(sync){Current=stage>0&&pendingStageUnits.Count>0&&Norm(pendingStageUnits.Peek().Text)==Norm(text)?pendingStageUnits.Dequeue():MakeUnit(text,stage);Current.Status="Đang đọc";Append("Bắt đầu đơn vị "+Current.Number+"; cue "+String.Join(",",Current.CueIds)+"; lời: "+text);}}
 public void Origin(bool cache){lock(sync){if(Current!=null){if(cache)Current.CacheCalls++;else Current.GeneratedCalls++;}}}
 public void Device(string value){lock(sync){if(!String.IsNullOrEmpty(value)&&devices.LastOrDefault()!=value){devices.Add(value);Append("Thiết bị app báo: "+value);}}}
 public void Natural(PacedSpeech p,double measured){lock(sync){if(Current!=null){Current.Before=measured;Current.Tts=p.SpeechSeconds;Current.PauseBefore=Math.Max(0,measured-p.SpeechSeconds);Current.PauseAfter=Current.PauseBefore;Append("Đơn vị "+Current.Number+": đo trước căn "+F(Current.Before)+"s; nghỉ app chèn "+F(p.PauseSeconds)+"s");}}}
 public void StageNatural(double measured){lock(sync){if(CurrentStage!=null)CurrentStage.Before=measured;}}
 public void Pacing(double scale,double reserve,double? measured=null){lock(sync){if(Current!=null){Current.PauseAfter=measured.HasValue&&Current.Tts.HasValue?Math.Max(0,measured.Value-Current.Tts.Value):Current.PauseBefore*scale;Current.Reserve=reserve;}}}
 public void Attempt(double speed,double measured,double target,string note){lock(sync){var a=new VoiceReportAttempt{Speed=speed,Measured=measured,Target=target,Note=note};if(Current!=null){Current.Attempts.Add(a);if(!Current.WorkingBefore.HasValue)Current.WorkingBefore=measured;Current.Target=target;}else if(CurrentStage!=null)CurrentStage.Attempts.Add(a);Append((Current!=null?"Đơn vị "+Current.Number:"Chặng "+(CurrentStage==null?0:CurrentStage.Number))+": tốc độ "+F(speed)+"x; đo "+F(measured)+"s; đích căn "+F(target)+"s; "+note);}}
 public void GapBefore(double gap,double breath){lock(sync){if(Current!=null){Current.GapBefore=gap;Current.BreathBefore=breath;}}}
 public void UnitDone(Cue cue,Wave w,bool fits,double gapAfter=0,double breathAfter=0){lock(sync){if(Current==null)return;Current.After=w.Duration;Current.Detail=cue.Status;Current.Speed=cue.Speed;Current.Start=cue.Start;Current.End=cue.Start+w.Duration;Current.GapAfter=gapAfter;Current.GapAfterKnown=fits;Current.BreathAfter=breathAfter;if(fits){if(lastTimelineUnit!=null&&(lastTimelineUnit.OriginalEnd??lastTimelineUnit.End).HasValue)lastTimelineUnit.GapAfter=Math.Max(0,cue.Start-(lastTimelineUnit.OriginalEnd??lastTimelineUnit.End).Value);lastTimelineUnit=Current;}Current.Status=fits?"Đã tạo âm thanh ứng viên":"Không khớp khung";Current.Error=fits?"":cue.Status;if(options.Prose&&options.TargetSeconds>0){Current.OriginalStart=Current.Start;Current.OriginalEnd=Current.End;Current.After=Current.Start=Current.End=null;Current.Status="Đã đo TXT trước căn đích";}Append("Đơn vị "+Current.Number+": "+Current.Status+"; sau căn "+F(Current.After)+"s; tốc độ lưu "+F(Current.Speed)+"x");Current=null;}}
 public void UnitBeforeStageDone(){lock(sync){if(Current!=null){Current.Status="Đã đo trước căn chặng; chưa có mốc sau căn riêng";Current=null;}}}
 public void StageDone(AnchorStage s,AnchorFit fit){lock(sync){var r=CurrentStage;if(r==null)return;r.Before=fit.Natural;r.After=fit.Audio==null?(double?)null:fit.Audio.Duration;r.Speed=fit.Speed;r.TailAdjustment=fit.SampleAdjustment;r.Status=fit.Success?"Đạt khung chặng":"Không khớp khung chặng";r.Reason=fit.Reason;foreach(var u in Units.Where(u=>u.Stage==s.Number)){u.Speed=fit.Speed;u.Status=fit.Success?"Đã đo trước căn; căn theo chặng đạt":"Chặng không khớp; chỉ có số đo trước căn";}Append("Chặng "+s.Number+": "+r.Status+"; trước "+F(r.Before)+"s; sau "+F(r.After)+"s; "+fit.Reason);CurrentStage=null;}}
 public void Finish(string outcome,string wav,Exception error){lock(sync){Outcome=outcome;Wav=wav??"";Error=error==null?"":error.Message;if(error!=null)CaptureFailure(error);Complete=true;if(outcome=="THÀNH CÔNG")foreach(var u in Units){if(u.Status=="Đã tạo âm thanh ứng viên")u.Status="Đã xuất trong WAV cuối";else if(u.Status=="Đã đo trước căn; căn theo chặng đạt")u.Status="Đã xuất cùng chặng; chưa có mốc sau căn riêng";}if(Current!=null){Current.Status=outcome=="ĐÃ DỪNG"?"Đã dừng tại đơn vị này":"Lỗi tại đơn vị này";Current.Error=Error;}if(CurrentStage!=null){CurrentStage.Status=outcome=="ĐÃ DỪNG"?"Đã dừng tại chặng":"Lỗi tại chặng";CurrentStage.Reason=Error;}if(PathName.Length>0){string tmp=PathName+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(tmp,Build(),new UTF8Encoding(false));File.Replace(tmp,PathName,null);}catch(Exception e){SaveWarning="Không hoàn thiện được báo cáo: "+e.Message;Append("KẾT THÚC: "+outcome+"; WAV="+Wav+"; lỗi="+Error);}finally{try{File.Delete(tmp);}catch{}}}Notify();}}
 static string F(double? n){return n.HasValue&&!Double.IsNaN(n.Value)&&!Double.IsInfinity(n.Value)?n.Value.ToString("0.000",CI):"chưa đo";}
 static string T(double? n){return n.HasValue&&n.Value>=0&&!Double.IsNaN(n.Value)&&!Double.IsInfinity(n.Value)?Scripts.Stamp(n.Value):"chưa xác định";}
 string Change(double speed){double percent=(speed/options.BaseSpeed-1)*100;return Math.Abs(percent)<.001?"giữ nguyên so với tốc độ gốc":(percent>0?"tăng ":"giảm ")+Math.Abs(percent).ToString("0.000",CI)+"% so với gốc "+F(options.BaseSpeed)+"x";}
 public string Build(){
  var byCue=new Dictionary<int,List<VoiceReportUnit>>();foreach(var u in Units)foreach(int id in u.CueIds){List<VoiceReportUnit> list;if(!byCue.TryGetValue(id,out list)){list=new List<VoiceReportUnit>();byCue[id]=list;}list.Add(u);}
  var b=new StringBuilder();Action<string> line=s=>b.Append(s).Append("\r\n");
  line("V15 VOICE REPORT · schema 3 · app "+typeof(VoiceRenderReport).Assembly.GetName().Version);line("Kết quả: "+Outcome);line("Bắt đầu UTC: "+started.ToString("o",CI)+"; đã chạy "+F(timer.Elapsed.TotalSeconds)+"s");line("Mục đích: "+context.Purpose);line("Nguồn: "+(String.IsNullOrEmpty(context.SourcePath)?"Kịch bản dán/mẫu chưa có file nguồn":System.IO.Path.GetFileName(context.SourcePath)));line("SHA256 file nguồn: "+sourceHash);line("SHA256 snapshot lời+mốc dùng trong app: "+HashText(String.Join("\n",sources.Select(c=>c.Id+"|"+c.Start.ToString("R",CI)+"|"+c.End.ToString("R",CI)+"|"+c.Prose+"|"+c.Speaker+"|"+c.Text))));line("Tổng đơn vị đã lên kế hoạch: "+Units.Count+"; có số đo trước căn: "+Units.Count(u=>u.Before.HasValue)+"; chưa đo: "+Units.Count(u=>!u.Before.HasValue)+"; chặng có kết quả: "+Stages.Count(s=>s.After.HasValue));line("WAV cuối của LẦN NÀY: "+(Wav.Length>0?Wav:"CHƯA XUẤT · các số sau căn bên dưới chỉ là âm thanh ứng viên"));line("Báo cáo: "+PathName);if(SaveWarning.Length>0)line("Lưu ý lưu báo cáo: "+SaveWarning);
  line("");line("GIỌNG VÀ THIẾT LẬP");line("Chế độ: "+(options.TwoVoices?"HAI GIỌNG · A / B · cùng một WAV":"MỘT GIỌNG"));if(options.TwoVoices){line("Giọng A: "+options.VoiceAInfo);line("Giọng B: "+options.VoiceBInfo);line("Nhãn [A] / [B] chỉ định tuyến, không đọc và không tính vào lời. Chi tiết engine bên dưới là engine đang/cuối được chọn; xem từng đơn vị và ánh xạ A/B để biết giọng thực tế.");}line("Ngôn ngữ: "+(engine!=null&&engine.Kind==EngineKind.VieNeu?"Tiếng Việt":"English theo nguồn giọng đã chọn"));line("Tên giọng: "+(engine==null?"chưa chọn":engine.VoiceName)+"; mã: "+context.VoiceKey);line("Engine/model: "+(engine==null?"chưa có":engine.Kind+" / "+engine.ModelFolder+" / speaker "+engine.Speaker));line("Nguồn giọng: "+context.VoiceSource);line("Đặc điểm: "+context.Description);line("Phong cách: "+context.Styles);line("Ghi chú của người dùng: "+context.UserNote);line("Loại giọng: "+(engine!=null&&!String.IsNullOrEmpty(engine.ReferencePath)?"sao chép · mẫu "+System.IO.Path.GetFileName(engine.ReferencePath)+" · SHA256 "+referenceHash:"giọng có sẵn"));line("Không đính kèm file âm thanh tham chiếu trong báo cáo.");line("Thiết bị yêu cầu: "+(engine==null?"chưa chọn":engine.DeviceMode));line("Thiết bị đã báo trong lần chạy: "+(devices.Count==0?"chưa có xác nhận; có thể chưa tổng hợp hoặc dùng cache":String.Join(" → ",devices)));line("Thiết bị của âm thanh lấy từ cache: không suy đoán từ thiết bị đang chọn.");line("Số chênh: dương = dài hơn đích, âm = ngắn hơn đích. Khóa SRT có thể dành chỗ nghỉ và biên 0.025s khi căn; ngắn hơn khung không tự động là lỗi, cần xem trạng thái tác vụ/chặng.");line("Timeline: "+(options.Anchored?"V15.6 · theo chặng":options.Prose?(options.TargetSeconds!=0||options.TargetRaw.Length>0?"TXT · căn thời lượng đích":"TXT · theo voice"):options.Locked?"Khóa SRT":"Linh hoạt theo voice"));line("Tốc độ gốc: "+F(options.BaseSpeed)+"x; giới hạn đặt: "+F(options.MinSpeed)+"–"+F(options.MaxSpeed)+"x; giới hạn áp dụng: "+F(Tempo.Minimum(options))+"–"+F(Tempo.Maximum(options))+"x; nhẹ ±10%: "+options.GentleFit);line("Ngắt nghỉ: "+options.Punctuation+"; phẩy="+F(options.CommaPause)+"s; chấm="+F(options.StopPause)+"s; hỏi/cảm="+F(options.QuestionPause)+"s; đoạn="+F(options.ParagraphPause)+"s; gap="+F(options.Gap)+"s");line("Hơi thở: "+(options.Breathing==BreathMode.None?"Không dùng":options.Breathing==BreathMode.Custom?"Tùy chọn":"Auto")+"; mỗi "+options.BreathEvery+" câu; mức="+F(options.BreathLevel*100)+"%; cân âm="+options.NormalizeLoudness+" / "+F(options.TargetLufs)+" LUFS");
  line("");line("CUE NGUỒN · nguyên văn dùng trong app trước khi ghép/căn");line("Số cue theo thứ tự trong app; file nguồn có thể đã được đánh lại số khi nhập.");if(rawSource.Length>0){line("Chưa phân tích được cue. Nguyên văn file đầu vào:");line(rawSource);}line("Timeline nguồn và mốc WAV là hai trường riêng. TXT không có timeline nguồn; không dùng mốc dự kiến như mốc đã đo.");foreach(var c in sources){List<VoiceReportUnit> used;if(!byCue.TryGetValue(c.Id,out used))used=new List<VoiceReportUnit>();string state=used.Count==0?"CHƯA CHẠY TỚI / chưa có số liệu":String.Join("; ",used.Select(u=>"đơn vị "+u.Number+": "+u.Status));line("#"+c.Id+" | "+(options.Prose||c.Prose?"TXT · chưa có timeline nguồn":T(c.Start)+" → "+T(c.End)+" | khung "+F(c.Duration)+"s")+" | "+c.Words+" đơn vị từ tách theo văn bản | khóa cuối chặng="+c.AnchorAfter);line("Giọng câu: "+(options.TwoVoices?SpeakerScript.Role(c):"A · một giọng"));line("Lời: "+c.Text);line("Trạng thái: "+state);}
  line("");line("ĐƠN VỊ LỜI ĐỌC · số đo âm thanh thực tế");foreach(var u in Units){line("Đơn vị "+u.Number+" | cue "+String.Join(",",u.CueIds)+" | chặng "+u.Stage+" | liên kết cue "+(u.ExactMap?"theo nội dung":"chỉ theo chặng; chưa xác định cue riêng"));line("Giọng thực tế: "+u.Speaker+" · "+u.Voice+" · mã "+u.VoiceKey+" · "+u.Engine+" · SHA256 mẫu "+u.ReferenceHash);line("Lời: "+u.Text);line("Trạng thái: "+u.Status);if(u.Detail.Length>0)line("Đánh giá của bộ căn: "+u.Detail);line("Trước căn tại tốc độ gốc: "+F(u.Before)+"s; đầu vào sau chỉnh nghỉ: "+F(u.WorkingBefore)+"s; sau căn đo RIÊNG: "+F(u.After)+"s");line("Audio TTS gốc (gồm nghỉ tự nhiên chưa tách riêng): "+F(u.Tts)+"s; tổng sau ghép nghỉ trong đơn vị: "+F(u.Before)+"s");line("Nghỉ app trong đơn vị: trước "+F(u.Before.HasValue?(double?)u.PauseBefore:null)+"s → sau chỉnh "+F(u.Before.HasValue?(double?)u.PauseAfter:null)+"s; dự phòng cuối câu "+F(u.Before.HasValue?(double?)u.Reserve:null)+"s. Nghỉ tự nhiên của model nằm trong audio, không tách giả số giây.");line("Trước đơn vị (trước căn chặng): gap "+F(u.Before.HasValue?(double?)u.GapBefore:null)+"s (gồm hơi thở "+F(u.Before.HasValue?(double?)u.BreathBefore:null)+"s); sau đơn vị (cue riêng): khoảng trống/gap "+F(u.GapAfterKnown?(double?)u.GapAfter:null)+"s (hơi thở "+F(u.GapAfterKnown?(double?)u.BreathAfter:null)+"s)");line("Nguồn audio: "+u.GeneratedCalls+" lượt yêu cầu tổng hợp (có thể gồm thử lại nội bộ), "+u.CacheCalls+" lượt dùng cache");if(u.Speed.HasValue)line("Tốc độ lưu: "+F(u.Speed)+"x; "+Change(u.Speed.Value)+(u.Stage>0?" · áp dụng TOÀN CHẶNG":""));if(u.OriginalStart.HasValue)line("Mốc đo TRƯỚC căn TXT đích: "+T(u.OriginalStart)+" → "+T(u.OriginalEnd));line("Mốc WAV đo riêng: "+T(u.Start)+" → "+T(u.End)+(Wav.Length==0?" · chỉ là ứng viên, chưa có WAV cuối":""));if(u.Stage>0)line("Chặng được đổi tốc độ chung; không chia đều hoặc suy ra mốc từng câu sau căn. Xem số đo chặng bên dưới.");Estimate(line,u.RequiredSpeed,u.Target,u.Attempts);Attempts(line,u.Attempts);if(u.Error.Length>0)line("Lý do: "+u.Error);}
  line("");line("CHẶNG V15.6 · không gán thời lượng chung thành số đo riêng từng cue");foreach(var s in Stages){line("Chặng "+s.Number+" | cue "+String.Join(",",s.CueIds)+" | nguồn "+T(s.Start)+" → "+T(s.End)+" | khung "+F(s.End-s.Start)+"s");line("Lời toàn chặng: "+s.Text);line("Kết quả: "+s.Status+" | trước căn (gồm nghỉ/hơi thở ghép): "+F(s.Before)+"s | sau căn: "+F(s.After)+"s | chênh sau căn-khung: "+F(s.After.HasValue?s.After-(s.End-s.Start):(double?)null)+"s | hiệu chỉnh đuôi: "+F(s.Speed.HasValue?(double?)s.TailAdjustment:null)+"s");if(s.Speed.HasValue)line("Tốc độ chặng: "+F(s.Speed)+"x; "+Change(s.Speed.Value));line("Thành phần TRƯỚC căn: audio TTS gốc (gồm nghỉ tự nhiên) "+F(s.Tts)+"s; nghỉ app trong đơn vị "+F(s.InnerPauses)+"s; nghỉ app giữa đơn vị (không gồm hơi thở) "+F(s.BetweenPauses)+"s; hơi thở "+F(s.Breaths)+"s");line("Khung chặng dùng chung cho toàn bộ lời/nghỉ/hơi thở. Sau đổi tốc độ chỉ đo tổng; không gán tỷ lệ thành số đo từng thành phần.");Estimate(line,s.RequiredSpeed,s.End-s.Start,s.Attempts);Attempts(line,s.Attempts);if(s.Reason.Length>0)line("Lý do: "+s.Reason);}
  if(options.AnchorResult!=null&&!String.IsNullOrEmpty(options.AnchorResult.AlignmentNote))line("Ghi chú SRT theo WAV: "+options.AnchorResult.AlignmentNote);
  if(options.AiRepair!=null){line("");line("LỊCH SỬ SỬA LỜI AI · CÙNG LẦN TẠO");line(options.AiRepair.BuildReport());}else if(!String.IsNullOrEmpty(options.AiReportPath)){line("");line("LỊCH SỬ AI ĐÃ ÁP DỤNG: "+options.AiReportPath);try{if(File.Exists(options.AiReportPath)&&new FileInfo(options.AiReportPath).Length<=10*1024*1024)line(File.ReadAllText(options.AiReportPath));}catch{line("Chưa đọc được lịch sử AI.");}}
  line("");TargetReport(line);line("LỖI / KẾT THÚC");Diagnostics(line);line(Error.Length>0?Error:"Không có lỗi tác vụ được ghi nhận.");line(Complete?"BÁO CÁO ĐÃ KẾT THÚC":"BÁO CÁO ĐANG GHI · nếu không có dấu kết thúc, tác vụ có thể đã bị ngắt đột ngột.");
  line("");line("HƯỚNG DẪN CHO CHAT TẠO PROMPT");line("Dùng đúng tên giọng, tốc độ gốc, giới hạn áp dụng và thời lượng đo trong báo cáo này. Đối chiếu nguyên văn, cue và mốc nguồn. Phần chưa đo không được dùng làm số liệu hiệu chuẩn. Đơn vị trong chặng chưa có mốc sau căn riêng không được suy ra bằng chia đều hoặc tỷ lệ.");line("Ưu tiên phân tích các đơn vị/chặng không khớp và lịch sử thử tốc độ; tốc độ % được tính so với tốc độ gốc, không mặc định so với 1.00x. Giữ cốt truyện, thứ tự sự kiện và điểm neo. Không tự giảm giọng sâu, thêm lời đệm hay suy ra một định mức số từ áp dụng cho mọi giọng. Bản sửa prompt/SRT cần render lại để xác nhận.");
  return b.ToString().Replace("chưa đos","chưa đo").Replace("chưa đox","chưa đo");
 }
 void Attempts(Action<string> line,List<VoiceReportAttempt> items){for(int i=0;i<items.Count;i++){var a=items[i];line("  Thử "+(i+1)+": "+F(a.Speed)+"x; atempo so với gốc "+F(a.Speed/options.BaseSpeed)+"; "+Change(a.Speed)+"; đo "+F(a.Measured)+"s; đích "+F(a.Target)+"s; chênh đo-đích "+F(a.Measured-a.Target)+"s; "+a.Note);}}
}
}
